function openOrientationAssessment(pushHash=true){ state.orientationQuizIndex=0; state.orientationQuizScore=0; state.orientationAnswered=false; renderOrientationQuestion(); showSection('lesson-detail',false); if(pushHash)history.pushState(null,'','#orientation/assessment'); }
function renderOrientationQuestion(){
  const i=state.orientationQuizIndex, q=ORIENTATION.assessment_questions[i];
  if(!q){
    const pct=Math.round(state.orientationQuizScore/ORIENTATION.assessment_questions.length*100); const pass=pct>=70;
    document.getElementById('lessonDetail').innerHTML=`<div class="backbar"><button class="backbtn" onclick="openOrientationCourse()">← Welcome & Orientation</button></div><div class="detail-hero"><span class="badge">Assessment Complete</span><h2>${pass?'Passed — '+pct+'%':'Review & Retake — '+pct+'%'}</h2><p>You answered ${state.orientationQuizScore} of ${ORIENTATION.assessment_questions.length} correctly. NHMEC lists a 70% minimum passing score for this orientation assessment.</p></div><div class="card"><h3>${pass?'Orientation assessment passed':'Keep studying'}</h3><p>${pass?'You may continue into your assigned NHMEC learning pathway after completing the other required orientation acknowledgments and assignments.':'Review the modules, required reading, and scope language, then retake the open-book assessment.'}</p><button class="btn btn-green" onclick="openOrientationAssessment(false)">Retake assessment</button></div>`; return;
  }
  const pct=Math.round(i/ORIENTATION.assessment_questions.length*100);
  document.getElementById('lessonDetail').innerHTML=`<div class="backbar"><button class="backbtn" onclick="openOrientationCourse()">← Welcome & Orientation</button></div><div class="detail-hero"><span class="badge">Final Open-Book Assessment</span><h2>Question ${i+1} of ${ORIENTATION.assessment_questions.length}</h2><p>Passing score: 70% minimum.</p></div><div class="progress"><span style="width:${pct}%"></span></div><div class="quiz-card"><h3>${esc(q.q)}</h3><div id="orientationAnswers">${q.options.map(o=>`<button class="answer" onclick="answerOrientation('${o.letter}',this)"><b>${o.letter}.</b> ${esc(o.text)}</button>`).join('')}</div><div class="quiz-feedback" id="orientationFeedback"></div><button id="orientationNext" class="btn btn-green" style="display:none" onclick="nextOrientationQuestion()">${i===ORIENTATION.assessment_questions.length-1?'See results':'Next question'}</button></div>`;
}
function answerOrientation(letter,btn){
  if(state.orientationAnswered)return; state.orientationAnswered=true; const q=ORIENTATION.assessment_questions[state.orientationQuizIndex];
  const buttons=[...document.querySelectorAll('#orientationAnswers .answer')]; buttons.forEach((b,idx)=>{ if(q.options[idx].letter===q.correct)b.classList.add('correct'); });
  if(letter!==q.correct)btn.classList.add('wrong'); else state.orientationQuizScore++;
  document.getElementById('orientationFeedback').innerHTML=letter===q.correct?'<b>Correct.</b>':'<b>Review this item.</b> The correct answer is highlighted.';
  document.getElementById('orientationNext').style.display='inline-block';
}
function nextOrientationQuestion(){ state.orientationQuizIndex++; state.orientationAnswered=false; renderOrientationQuestion(); window.scrollTo({top:0,behavior:'smooth'}); }


