function biblicalHerbalismResourcesHTML(){
  return `<div class="section-head"><div><h2>Course Resources</h2><p>Original NHMEC guidebooks and lesson PDFs are included in the app.</p></div></div><div class="card-grid">${BIBLICAL_HERBALISM.resources.map(r=>`<div class="card resource-file"><div class="file-icon">📄</div><div><h3>${esc(r.title)}</h3><p>${esc(r.note)}</p><a class="btn btn-sage file-link" href="${encodeURI(r.file)}" target="_blank" rel="noopener">Open PDF</a></div></div>`).join('')}</div>`;
}
function renderSourceLessonText(text){
  const blocks=String(text||'').split(/\n\s*\n/).map(x=>x.trim()).filter(Boolean);
  const headingWords=/^(Lesson Overview|Lesson Scripture Foundations|Lesson Objectives|Opening Teaching|Student Reflection|Vocabulary Words|Closing Prayer|Instructor Closing|Lesson \d+ Summary|Teacher.?s Teaching Notes|Case Study|Class Activity|Biblical Food & Herb Study Practice|Biblical Herb Study|Herbal Ministry Reflection|Final Reflection|Safety|Scope|What Is |God as |Plants as |The |Spirit|Soul|Body|Prayer|Scripture|Referral|Discernment|Creator Worship|Creation Worship)/i;
  return blocks.map(b=>{
    const lines=b.split('\n').map(x=>x.trim()).filter(Boolean);
    const joined=lines.join(' ');
    if(lines.length===1 && (headingWords.test(lines[0]) || (lines[0].length<70 && !/[.!?]$/.test(lines[0])))) return `<h3>${esc(lines[0])}</h3>`;
    if(lines.every(x=>/^\d+[.)]\s+/.test(x))) return `<ol>${lines.map(x=>`<li>${esc(x.replace(/^\d+[.)]\s+/,''))}</li>`).join('')}</ol>`;
    if(lines.length>=3 && lines.every(x=>x.length<90) && !/[.!?]$/.test(lines[0])) return `<ul>${lines.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;
    return `<p>${esc(joined)}</p>`;
  }).join('');
}
